/**
 * BoatraceOpenAPI クライアント
 *
 * 非公式APIです。BOATRACE公式サイト・関連団体とは無関係で、
 * 更新間隔があるため速報性・正確性は保証されません。
 * GitHub Pages 配信のためブラウザから直接 fetch できます（CORS制限なし）。
 */

export const ENDPOINTS = {
  programs: "https://boatraceopenapi.github.io/programs/v2",
  previews: "https://boatraceopenapi.github.io/previews/v2",
  results: "https://boatraceopenapi.github.io/results/v2",
};

/**
 * オッズ（boatrace.jp）・直前情報の追加データ（BOATCAST）の取得用プロキシの
 * ベースURL。どちらもブラウザから直接fetchするとCORSで拒否されるため、
 * 何らかのサーバーを経由する必要がある。
 *
 * .env に REACT_APP_PROXY_BASE を設定すると、デプロイした Cloudflare Workers
 * （cf-worker フォルダ）を使うようになる。何も設定しなければ、ローカルの
 * 取得用サーバー（uipath-server フォルダで `node index.js`）を使う従来通りの
 * 動作になる。値は npm run build 時に埋め込まれるので、.env を変更したら
 * ビルドし直すこと。
 */
export const PROXY_BASE = process.env.REACT_APP_PROXY_BASE || "http://localhost:5001";

export function ymdOf(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}${m}${d}`;
}

export function urlFor(kind, date) {
  return `${ENDPOINTS[kind]}/${date.getFullYear()}/${ymdOf(date)}.json`;
}

export async function fetchJson(url, { signal } = {}) {
  const res = await fetch(url, { signal, cache: "no-store" });
  if (!res.ok) {
    const err = new Error(`HTTP ${res.status}`);
    err.status = res.status;
    throw err;
  }
  return res.json();
}

export function fetchDaily(kind, date, opts) {
  return fetchJson(urlFor(kind, date), opts);
}

/* ------------------------------------------------------------------ *
 * 防御的パース
 * トップレベルのキー名や入れ子フィールド名はバージョンにより差異が
 * ありうるため、形状から目的の配列を探し出す方式にしている。
 * ------------------------------------------------------------------ */

export function findRacesArray(json) {
  if (!json || typeof json !== "object") return [];
  if (Array.isArray(json)) return json;
  for (const v of Object.values(json)) {
    if (
      Array.isArray(v) && v.length && v[0] && typeof v[0] === "object" &&
      ("race_stadium_number" in v[0] || "stadium_number" in v[0])
    ) {
      return v;
    }
  }
  return [];
}

export function findBoatsArray(raceObj) {
  if (!raceObj || typeof raceObj !== "object") return [];
  for (const v of Object.values(raceObj)) {
    if (
      Array.isArray(v) && v.length && v[0] && typeof v[0] === "object" &&
      ("racer_boat_number" in v[0] || "boat_number" in v[0])
    ) {
      return v;
    }
  }
  return [];
}

/** 候補キー名を順に探して最初に見つかった値を返す */
export function pick(obj, keys, fallback = undefined) {
  if (!obj) return fallback;
  for (const k of keys) {
    const v = obj[k];
    if (v !== undefined && v !== null && v !== "") return v;
  }
  return fallback;
}

export function num(v, fallback = undefined) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

/**
 * スタートタイミング表示用。「0.10」のように小数第2位が0でも省略せず表示する。
 * フライング・出遅れ（F/L始まり）はそのまま返す。
 */
export function fmtSt(v) {
  if (v === undefined || v === null || v === "") return "―";
  const s = String(v).trim();
  if (/^[FL]/i.test(s)) return s;
  const n = Number(s);
  return Number.isFinite(n) ? n.toFixed(2) : s;
}

/* ------------------------------------------------------------------ *
 * 数値コードの対応表
 * programs/previews/results v2 は天候・風向・決まり手を数値コードで
 * 返す（テキストではない）。公式の一次ドキュメントが見当たらないため、
 * 競艇の成績データで広く使われている一般的な対応関係を採用している。
 * ズレがあれば実際の日本語表記と突き合わせて調整すること。
 * ------------------------------------------------------------------ */

export const WEATHER_LABELS = {
  1: "晴", 2: "曇り", 3: "雨", 4: "雪", 5: "霧", 6: "台風",
};

export const WIND_DIRECTION_LABELS = {
  1: "北", 2: "北北東", 3: "北東", 4: "東北東", 5: "東", 6: "東南東", 7: "南東", 8: "南南東",
  9: "南", 10: "南南西", 11: "南西", 12: "西南西", 13: "西", 14: "西北西", 15: "北西", 16: "北北西",
};

export const TECHNIQUE_LABELS = {
  1: "逃げ", 2: "差し", 3: "まくり", 4: "まくり差し", 5: "抜き", 6: "恵まれ",
};

/** 英語キーの賭式名 → 日本語ラベル（results の payouts オブジェクトのキー） */
export const BET_TYPE_LABELS = {
  win: "単勝",
  place: "複勝",
  exacta: "2連単",
  quinella: "2連複",
  quinella_place: "拡連複",
  trifecta: "3連単",
  trio: "3連複",
};

/**
 * results v2 の payouts は { win: [{combination, payout}], exacta: [...], ... }
 * という「賭式名 → 配列」の形。ResultsPanel が期待するフラットな配列
 * [{ type, combination, payoff }, ...] に変換する。
 */
export function flattenPayouts(payouts) {
  if (!payouts || typeof payouts !== "object" || Array.isArray(payouts)) return [];
  const out = [];
  for (const [betType, rows] of Object.entries(payouts)) {
    if (!Array.isArray(rows)) continue;
    for (const row of rows) {
      out.push({
        type: BET_TYPE_LABELS[betType] || betType,
        combination: pick(row, ["combination", "number", "combo"], ""),
        payoff: num(pick(row, ["payout", "payoff", "amount", "money"], 0), 0),
        popularity: pick(row, ["popularity", "pop", "rank"]),
      });
    }
  }
  return out;
}

/* ---- よく使うフィールドのアクセサ（候補キー名はここに集約） ---- */

export const F = {
  stadium: (r) => num(pick(r, ["race_stadium_number", "stadium_number"])),
  raceNo: (r) => num(pick(r, ["race_number", "race_no"])),
  raceTitle: (r) => pick(r, ["race_title", "title"]),
  raceSubtitle: (r) => pick(r, ["race_subtitle", "subtitle"]),
  raceGrade: (r) => pick(r, ["race_grade_number", "race_grade", "grade"]),
  closedAt: (r) => pick(r, ["race_closed_at", "close_time", "vote_limit"]),
  distance: (r) => num(pick(r, ["race_distance", "distance"])),

  lane: (b, i = 0) => num(pick(b, ["racer_boat_number", "boat_number", "lane"]), i + 1),
  racerNo: (b) => pick(b, ["racer_number", "registration_number"]),
  racerName: (b) => pick(b, ["racer_name", "name"]),
  racerClass: (b) => pick(b, ["racer_class_number", "racer_class", "class"]),
  branch: (b) => pick(b, ["racer_branch_number", "racer_branch", "branch"]),
  age: (b) => pick(b, ["racer_age", "age"]),
  weight: (b) => pick(b, ["racer_weight", "weight"]),
  flying: (b) => num(pick(b, ["racer_flying_count", "flying_count", "flying"]), 0),
  late: (b) => num(pick(b, ["racer_late_count", "late_count", "late"]), 0),

  natWin: (b) => pick(b, ["racer_national_top_1_percent", "national_win_rate"]),
  natTop2: (b) => pick(b, ["racer_national_top_2_percent", "national_top_2_percent"]),
  natTop3: (b) => pick(b, ["racer_national_top_3_percent", "national_top_3_percent"]),
  locWin: (b) => pick(b, ["racer_local_top_1_percent", "local_win_rate"]),
  locTop2: (b) => pick(b, ["racer_local_top_2_percent", "local_top_2_percent"]),
  locTop3: (b) => pick(b, ["racer_local_top_3_percent", "local_top_3_percent"]),

  motorNo: (b) => pick(b, ["racer_assigned_motor_number", "motor_number"]),
  motorTop2: (b) => pick(b, ["racer_assigned_motor_top_2_percent", "motor_top_2_percent"]),
  motorTop3: (b) => pick(b, ["racer_assigned_motor_top_3_percent", "motor_top_3_percent"]),
  boatNo: (b) => pick(b, ["racer_assigned_boat_number", "boat_no"]),
  boatTop2: (b) => pick(b, ["racer_assigned_boat_top_2_percent", "boat_top_2_percent"]),
  boatTop3: (b) => pick(b, ["racer_assigned_boat_top_3_percent", "boat_top_3_percent"]),
  avgSt: (b) => pick(b, ["racer_average_start_timing", "average_start_timing"]),

  exhibitionTime: (b) => pick(b, ["racer_exhibition_time", "exhibition_time"]),
  tilt: (b) => pick(b, ["racer_tilt_adjustment", "racer_tilt", "tilt"]),
  beforeWeight: (b) => pick(b, ["racer_weight_before", "racer_weight", "weight"]),
  /** 前走比の体重差（previews固有。直前情報が出るまでは0で返ってくる）。 */
  weightAdjustment: (b) => pick(b, ["racer_weight_adjustment"]),
  courseNo: (b) => num(pick(b, ["racer_course_number", "course_number", "entry_course"])),

  weather: (r) => {
    const coded = pick(r, ["race_weather_number"]);
    if (coded !== undefined) return WEATHER_LABELS[Number(coded)] || String(coded);
    return pick(r, ["race_weather", "weather", "weather_condition"]);
  },
  windSpeed: (r) => pick(r, ["race_wind", "wind_speed", "wind"]),
  windDir: (r) => {
    const coded = pick(r, ["race_wind_direction_number"]);
    if (coded !== undefined) return WIND_DIRECTION_LABELS[Number(coded)] || String(coded);
    return pick(r, ["race_wind_direction", "wind_direction"]);
  },
  wave: (r) => pick(r, ["race_wave", "wave_height", "wave"]),
  airTemp: (r) => pick(r, ["race_temperature", "air_temperature", "temperature"]),
  waterTemp: (r) => pick(r, ["race_water_temperature", "water_temperature"]),

  place: (b) => num(pick(b, ["racer_place_number", "result", "arrival", "place"])),
  st: (b) => pick(b, ["racer_start_timing", "start_timing", "start_time"]),
  /**
   * 決まり手はレース全体に1つ（1着艇の勝ち方）で、boats の各艇ではなく
   * レースオブジェクト側に race_technique_number として載っている。
   * そのため引数には「艇」ではなく「レース」を渡すこと。
   */
  kimarite: (r) => {
    const coded = pick(r, ["race_technique_number"]);
    if (coded !== undefined) return TECHNIQUE_LABELS[Number(coded)] || String(coded);
    return pick(r, ["winning_technique", "kimarite", "race_technique"]);
  },
  /** 結果レースの払戻金をフラットな配列で返す（実体は results の payouts オブジェクト） */
  payoffs: (r) => {
    const payouts = pick(r, ["payouts"]);
    if (payouts && typeof payouts === "object") return flattenPayouts(payouts);
    return pick(r, ["race_payoffs", "payoffs_legacy", "payoff"]);
  },
};

/** 指定日のJSONから 場・R が一致するレースを取り出す */
export function selectRace(json, stadium, raceNo) {
  const arr = findRacesArray(json);
  return arr.find((r) => F.stadium(r) === Number(stadium) && F.raceNo(r) === Number(raceNo)) || null;
}
