import React from "react";
import { X } from "lucide-react";
import { stadiumName } from "../constants.js";
import ResultsPanel from "./ResultsPanel.jsx";

/**
 * 今節成績・過去10走の行をクリックしたときに、そのレースの結果
 * （全選手のスタートタイミング・着順・払戻金など）を表示するモーダル。
 * 表示だけの ResultsPanel をそのまま流用する。
 */
export default function RaceResultModal({ race, stadiumNo, ymd, raceNo, onClose }) {
  const dateLabel = ymd ? `${ymd.slice(0, 4)}/${ymd.slice(4, 6)}/${ymd.slice(6, 8)}` : "";
  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center">
      <div className="absolute inset-0 bg-black/60" onClick={onClose} />
      <div className="relative w-full sm:max-w-md max-h-[85vh] bg-base border border-line rounded-t-2xl sm:rounded-2xl overflow-hidden flex flex-col">
        <div className="flex items-center gap-2 px-4 py-3 border-b border-line shrink-0">
          <span className="font-bold text-ink text-sm">{stadiumName(stadiumNo)} {raceNo}R</span>
          <span className="text-[10px] text-sub2">{dateLabel}</span>
          <button onClick={onClose} className="ml-auto p-1 text-sub2 hover:text-ink" aria-label="閉じる"><X size={18} /></button>
        </div>
        <div className="overflow-y-auto px-4 py-3">
          <ResultsPanel race={race} />
        </div>
      </div>
    </div>
  );
}
