import React, { useEffect, useMemo, useState } from "react";
import { X, Trophy } from "lucide-react";
import { LineChart, Line, XAxis, YAxis, ResponsiveContainer, Dot, ReferenceLine, Tooltip } from "recharts";
import { fmtSt } from "../lib/api.js";
import { buildSameCourseHistory, fetchSeasonHistoryForRacer } from "../lib/aggregate.js";
import { OUTCOME_COLORS, ABNORMAL_FINISH_NOTES } from "../constants.js";
import { LaneBadge, GradeBadge, SectionLabel, Spinner, Notice } from "./ui.jsx";
import RaceResultModal from "./RaceResultModal.jsx";

const CHART_SLOTS = 10;

/** トップスタートとの差。正なら"+0.03"、0以下ならそのまま"-0.05"のように表示する。 */
function fmtStGap(gap) {
  if (gap === null || gap === undefined || !Number.isFinite(gap)) return "―";
  return gap > 0 ? `+${gap.toFixed(2)}` : gap.toFixed(2);
}

function ChartTooltip({ active, payload }) {
  if (!active || !payload?.length) return null;
  const p = payload[0].payload;
  if (p.勝率 == null) return null;
  return (
    <div className="bg-base border border-line rounded-md px-2 py-1.5 text-[10px] leading-relaxed">
      <div className="text-ink font-semibold">{p.stadiumName} <GradeBadge grade={p.grade} short /></div>
      <div className="text-sub2">勝率 <span className="text-ink font-bold tabular-nums">{p.勝率.toFixed(2)}</span></div>
    </div>
  );
}

/**
 * 選手名クリックのたびに、端末には何も保存せず
 * BoatraceOpenAPI（programs+results）から直接まとめて取得し直す
 * （過去10節ぶん見つかるまで90日ずつ遡る）。取得が終わったら使い捨て
 * （このモーダルを閉じれば破棄される）。
 */
export default function RacerStatsModal({ racer, stadium, ymd, onClose }) {
  const [progress, setProgress] = useState({ done: 0, total: 0, round: 1 });
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [venueOnly, setVenueOnly] = useState(false);
  const [openRace, setOpenRace] = useState(null);

  useEffect(() => {
    let alive = true;
    const ac = new AbortController();
    setProgress({ done: 0, total: 0, round: 1 });
    setData(null);
    setError(null);
    setVenueOnly(false);

    (async () => {
      try {
        const { all, seasons } = await fetchSeasonHistoryForRacer(racer.racerNo, {
          signal: ac.signal,
          excludeMeet: { stadium, ymd },
          onProgress: (p) => alive && setProgress(p),
        });
        if (!alive) return;
        const laneHistory = buildSameCourseHistory(all, racer.racerNo, racer.lane, 10);
        if (!alive) return;
        setData({ seasons, laneHistory, total: all.length });
      } catch (e) {
        if (alive && e?.name !== "AbortError") setError(e);
      }
    })();

    return () => {
      alive = false;
      ac.abort();
    };
  }, [racer.racerNo, racer.lane, stadium, ymd]);

  const seasons = useMemo(() => {
    const allSeasons = data?.seasons ?? [];
    return (venueOnly ? allSeasons.filter((s) => s.stadium === Number(stadium)) : allSeasons).slice(-CHART_SLOTS);
  }, [data, venueOnly, stadium]);

  const validRates = seasons.map((s) => s.winRate).filter((v) => Number.isFinite(v));
  const avg = validRates.length ? validRates.reduce((a, b) => a + b, 0) / validRates.length : null;

  // 常に10枠ぶん表示する（データが少ない場合は左側を空欄で埋める）
  const pad = Math.max(0, CHART_SLOTS - seasons.length);
  const chartData = [
    ...Array.from({ length: pad }, (_, i) => ({ name: "", 勝率: null, color: null, key: `pad${i}` })),
    ...seasons.map((s, i) => ({
      name: s.shortDate,
      勝率: Number.isFinite(s.winRate) ? s.winRate : null,
      color: OUTCOME_COLORS[s.outcome] || OUTCOME_COLORS["不明"],
      stadiumName: s.stadiumName,
      grade: s.grade,
      key: `s${i}`,
    })),
  ];
  // 節間でそこまで大きく変わらないため、実際の値の近辺までズームする
  const [minRate, maxRateRaw] = validRates.length
    ? [Math.min(...validRates), Math.max(...validRates)]
    : [0, 8];
  const rateSpan = Math.max(0.6, maxRateRaw - minRate);
  const chartDomain = [
    Math.max(0, Number((minRate - rateSpan * 0.35).toFixed(2))),
    Number((maxRateRaw + rateSpan * 0.35).toFixed(2)),
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center">
      <div className="absolute inset-0 bg-black/60" onClick={onClose} />
      <div className="relative w-full sm:max-w-lg max-h-[88vh] bg-base border border-line rounded-t-2xl sm:rounded-2xl overflow-hidden flex flex-col">
        <div className="flex items-center gap-2 px-4 py-3 border-b border-line shrink-0">
          <LaneBadge lane={racer.lane} />
          <span className="font-bold text-ink">{racer.name}</span>
          <span className="text-[10px] text-sub2">{racer.racerNo}</span>
          <button onClick={onClose} className="ml-auto p-1 text-sub2 hover:text-ink" aria-label="閉じる"><X size={18} /></button>
        </div>

        <div className="overflow-y-auto px-4 py-3">
          {error && <Notice tone="warn">取得に失敗しました：{String(error.message || error)}</Notice>}

          {!data && !error && (
            <Spinner
              label={
                progress.round > 1
                  ? `公式サイトから取得中…（10節に届かないため追加取得中: ${progress.round}周目 ${progress.done}/${progress.total}日）`
                  : `公式サイトから取得中… (${progress.done}/${progress.total}日)`
              }
            />
          )}

          {data && (
            <div className="space-y-4">
              {data.total === 0 && (
                <Notice tone="warn">
                  遡れる範囲を確認しましたが、この選手の結果データが見つかりませんでした。
                </Notice>
              )}

              <div>
                <div className="flex items-center justify-between mb-1.5">
                  <SectionLabel>過去{CHART_SLOTS}節の勝率（各節最終日時点の公式全国勝率）</SectionLabel>
                  <div className="flex gap-1 shrink-0">
                    {[{ k: false, l: "全場" }, { k: true, l: "当地" }].map((v) => (
                      <button
                        key={String(v.k)}
                        onClick={() => setVenueOnly(v.k)}
                        className={"px-2 py-0.5 rounded text-[10px] font-semibold border " +
                          (venueOnly === v.k ? "bg-accent border-accent text-base" : "bg-panel border-line text-sub2")}
                      >
                        {v.l}
                      </button>
                    ))}
                  </div>
                </div>
                <div className="bg-panel border border-line rounded-lg p-2.5">
                  <div className="flex items-center justify-between mb-1.5">
                    <span className="text-[10px] text-sub2">{seasons.length}節の平均</span>
                    <span className="text-sm font-bold tabular-nums text-amber">{avg !== null ? avg.toFixed(2) : "―"}</span>
                  </div>
                  {seasons.length ? (
                    <>
                      <div style={{ width: "100%", height: 140 }}>
                        <ResponsiveContainer>
                          <LineChart data={chartData} margin={{ top: 4, right: 4, left: -22, bottom: 0 }}>
                            <XAxis dataKey="name" tick={{ fontSize: 9, fill: "#7C93A8" }} axisLine={{ stroke: "#1F3B52" }} tickLine={false} />
                            <YAxis domain={chartDomain} tick={{ fontSize: 9, fill: "#7C93A8" }} axisLine={false} tickLine={false} />
                            {avg !== null && <ReferenceLine y={avg} stroke="#2FB6A8" strokeDasharray="3 3" />}
                            <Tooltip cursor={{ stroke: "#1F3B52" }} content={<ChartTooltip />} />
                            <Line
                              type="monotone"
                              dataKey="勝率"
                              stroke="#2FB6A8"
                              strokeWidth={2}
                              connectNulls={false}
                              isAnimationActive={false}
                              dot={(props) => {
                                const { cx, cy, payload } = props;
                                if (payload.勝率 == null) return null;
                                return <Dot key={payload.key} cx={cx} cy={cy} r={4} fill={payload.color} stroke="#0B1E2E" strokeWidth={1} />;
                              }}
                              activeDot={{ r: 6 }}
                            />
                          </LineChart>
                        </ResponsiveContainer>
                      </div>
                      <div className="flex flex-wrap gap-x-2.5 gap-y-1 mt-1.5">
                        {Object.entries(OUTCOME_COLORS).filter(([k]) => k !== "不明").map(([l, c]) => (
                          <span key={l} className="flex items-center gap-1 text-[9px] text-sub2">
                            <span className="w-2 h-2 rounded-sm" style={{ background: c }} />{l}
                          </span>
                        ))}
                      </div>
                      <div className="text-[9px] text-weak mt-1.5 leading-relaxed">
                        点は各節の最終戦（優勝戦/準優勝戦/予選いずれか本人が出走した最後のレース）の時点で
                        公開されていた公式全国勝率です。節ごとの実際の勝ち点とは異なる参考値です。
                      </div>
                    </>
                  ) : (
                    <div className="text-[11px] text-weak py-4 text-center">この選手の節データがまだありません。</div>
                  )}
                </div>
              </div>

              <div>
                <SectionLabel>予選順位と最終結果</SectionLabel>
                <div className="bg-panel border border-line rounded-lg p-2.5 scroll-x">
                  <table className="w-full text-[10px] min-w-[320px]">
                    <thead>
                      <tr className="text-sub2">
                        <th className="text-left font-normal py-1 pl-1">期間</th>
                        <th className="text-left font-normal py-1">場</th>
                        <th className="text-left font-normal py-1">格</th>
                        <th className="text-right font-normal py-1">勝率</th>
                        <th className="text-right font-normal py-1">予選順位</th>
                        <th className="text-left font-normal py-1 pl-2 pr-1">結果</th>
                      </tr>
                    </thead>
                    <tbody>
                      {[...seasons].reverse().map((s, i) => (
                        <tr key={i} className="border-t border-line">
                          <td className="py-1.5 pl-1 text-sub tabular-nums whitespace-nowrap">{s.period}</td>
                          <td className="py-1.5 text-sub whitespace-nowrap">{s.stadiumName}</td>
                          <td className="py-1.5"><GradeBadge grade={s.grade} /></td>
                          <td className="py-1.5 text-right font-semibold tabular-nums text-ink">
                            {Number.isFinite(s.winRate) ? s.winRate.toFixed(2) : "―"}
                          </td>
                          <td className="py-1.5 text-right tabular-nums text-sub">
                            {s.prelimRank ? `${s.prelimRank}/${s.prelimTotal}` : "―"}
                          </td>
                          <td className="py-1.5 pl-2 pr-1 whitespace-nowrap">
                            <span
                              className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded font-semibold"
                              style={{ background: OUTCOME_COLORS[s.outcome] || OUTCOME_COLORS["不明"], color: "#12283C" }}
                              title={s.abnormalCode ? ABNORMAL_FINISH_NOTES[s.abnormalCode] : undefined}
                            >
                              {s.outcome === "優勝" && <Trophy size={9} />}{s.outcomeLabel}
                            </span>
                          </td>
                        </tr>
                      ))}
                      {!seasons.length && <tr><td colSpan={6} className="py-3 text-center text-weak">データがありません</td></tr>}
                    </tbody>
                  </table>
                </div>
              </div>

              <div>
                <SectionLabel>過去10走（同{racer.lane}コース）</SectionLabel>
                <div className="bg-panel border border-line rounded-lg p-2.5 scroll-x">
                  <table className="w-full text-[10px] min-w-[320px]">
                    <thead>
                      <tr className="text-sub2">
                        <th className="text-left font-normal py-1 pl-1">日付</th>
                        <th className="text-left font-normal py-1">場</th>
                        <th className="text-left font-normal py-1">格</th>
                        <th className="text-left font-normal py-1">R</th>
                        <th className="text-center font-normal py-1">進入</th>
                        <th className="text-center font-normal py-1">着順</th>
                        <th className="text-right font-normal py-1">ST</th>
                        <th className="text-right font-normal py-1">トップ差</th>
                        <th className="text-left font-normal py-1 pl-2 pr-1">決まり手</th>
                      </tr>
                    </thead>
                    <tbody>
                      {data.laneHistory.map((r, i) => (
                        <tr key={i} className="border-t border-line cursor-pointer hover:bg-line/40" onClick={() => setOpenRace(r)}>
                          <td className="py-1 pl-1 text-sub tabular-nums whitespace-nowrap">{r.date}</td>
                          <td className="py-1 text-sub whitespace-nowrap">{r.stadium}</td>
                          <td className="py-1"><GradeBadge grade={r.grade} short /></td>
                          <td className="py-1 text-sub tabular-nums">{r.raceNo}R</td>
                          <td className="py-1 text-center"><LaneBadge lane={r.course} size="xs" /></td>
                          <td className="py-1 text-center font-semibold tabular-nums" style={{ color: r.place === 1 ? "#F2A93B" : "#EAF1F7" }}>{r.place ?? "―"}</td>
                          <td className="py-1 text-right text-sub tabular-nums">{fmtSt(r.st)}</td>
                          <td className="py-1 text-right text-sub2 tabular-nums">{fmtStGap(r.stGap)}</td>
                          <td className="py-1 pl-2 pr-1 text-sub whitespace-nowrap">{r.kimarite || "―"}</td>
                        </tr>
                      ))}
                      {!data.laneHistory.length && <tr><td colSpan={9} className="py-3 text-center text-weak">同コースでの出走データがありません</td></tr>}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {openRace && (
        <RaceResultModal
          race={openRace.raceRef}
          stadiumNo={openRace.stadiumNo}
          ymd={openRace.ymd}
          raceNo={openRace.raceNo}
          onClose={() => setOpenRace(null)}
        />
      )}
    </div>
  );
}
