/**
 * オッズ関連のユーティリティ。
 *
 * オッズ・投票数は BoatraceOpenAPI に含まれず、公式サイトもJSONを
 * 配信していない。ブラウザから boatrace.jp を直接 fetch すると CORS で
 * ブロックされるため、ローカルの取得用サーバー（uipath-server）を経由して
 * 公式サイトのオッズページを取得・解析している（自動取得できない/
 * ブロックされた場合の保険として、手入力・貼り付けのロジックも残す）。
 */

export const BET_TYPES = {
  win: { label: "単勝", size: 1, ordered: false },
  place: { label: "複勝", size: 1, ordered: false },
  exacta: { label: "2連単", size: 2, ordered: true },
  quinella: { label: "2連複", size: 2, ordered: false },
  quinella_place: { label: "拡連複", size: 2, ordered: false },
  trifecta: { label: "3連単", size: 3, ordered: true },
  trio: { label: "3連複", size: 3, ordered: false },
};

/** 組番キーの正規化（順不同式は昇順に並べ替える） */
export function comboKey(type, combo) {
  const def = BET_TYPES[type];
  const arr = def?.ordered ? combo : [...combo].sort((a, b) => a - b);
  return arr.join("-");
}

/** 合成オッズ = 1 ÷ Σ(1 ÷ 各点のオッズ) */
export function syntheticOdds(oddsList) {
  const valid = oddsList.map(Number).filter((n) => Number.isFinite(n) && n > 0);
  if (!valid.length) return null;
  return 1 / valid.reduce((s, o) => s + 1 / o, 0);
}

/** オッズ帯カラー。10倍未満=赤、1000倍以上=黄、それ以外は通常色（白）。 */
export function oddsBandColor(o) {
  if (!Number.isFinite(o)) return { bg: "#12283C", fg: "#3D5266" };
  if (o < 10) return { bg: "#E5433D", fg: "#FFFFFF" };
  if (o >= 1000) return { bg: "#F2C438", fg: "#1A2A3A" };
  return { bg: "#EAF1F7", fg: "#12283C" };
}

export const ODDS_BANDS = [
  ["〜9.9", "#E5433D"], ["10〜999", "#EAF1F7"], ["1000〜", "#F2C438"],
];

/**
 * テキストからオッズを一括取り込みする。
 * 「1-2-3 6.8」「1=2 4.5」「1 2 3 12.4」等の行を許容する。
 * 戻り値: { "1-2-3": 6.8, ... }
 */
export function parseOddsText(text, type) {
  const def = BET_TYPES[type];
  const out = {};
  if (!text || !def) return out;
  for (const rawLine of String(text).split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line) continue;
    const m = line.match(/^([\d\s\-=・,>→]+?)\s+([\d.]+)\s*倍?$/);
    if (!m) continue;
    const nums = m[1].match(/\d/g);
    const odds = Number(m[2]);
    if (!nums || nums.length !== def.size || !Number.isFinite(odds)) continue;
    const combo = nums.map(Number);
    if (combo.some((n) => n < 1 || n > 6)) continue;
    if (new Set(combo).size !== combo.length) continue;
    out[comboKey(type, combo)] = odds;
  }
  return out;
}

/** 組み合わせの列挙 */
export function enumerateCombos(type) {
  const def = BET_TYPES[type];
  const lanes = [1, 2, 3, 4, 5, 6];
  if (def.size === 1) return lanes.map((n) => [n]);
  const out = [];
  if (def.size === 2) {
    for (const a of lanes) for (const b of lanes) {
      if (a === b) continue;
      if (!def.ordered && a > b) continue;
      out.push([a, b]);
    }
  } else {
    for (const a of lanes) for (const b of lanes) for (const c of lanes) {
      if (a === b || b === c || a === c) continue;
      if (!def.ordered && !(a < b && b < c)) continue;
      out.push([a, b, c]);
    }
  }
  return out;
}
