import React from "react";
import { findBoatsArray, F, pick, fmtSt } from "../lib/api.js";
import { normalizeKimarite } from "../lib/aggregate.js";
import { LaneBadge, Stat, Notice, RawJson } from "./ui.jsx";

export default function ResultsPanel({ race }) {
  if (!race) return <Notice>この日・このレースの結果データが見つかりません（未開催・未確定の可能性があります）。</Notice>;

  const boats = [...findBoatsArray(race)].sort((a, b) => {
    const pa = F.place(a) ?? 99;
    const pb = F.place(b) ?? 99;
    return pa - pb;
  });
  const payoffs = F.payoffs(race);
  // 決まり手はレースに1つ（1着艇の勝ち方）。艇ごとではなくレース側にある。
  const raceKimarite = normalizeKimarite(F.kimarite(race));

  return (
    <div>
      <div className="space-y-1.5">
        {!boats.length && <Notice>結果情報が見つかりませんでした。</Notice>}
        {boats.map((b, i) => {
          const lane = F.lane(b, i);
          const place = F.place(b);
          const k = place === 1 ? raceKimarite : null;
          return (
            <div key={lane} className="flex items-center gap-2 bg-panel border border-line rounded-lg p-2.5">
              <span className="w-6 text-center font-bold text-amber tabular-nums">{place ?? "―"}</span>
              <LaneBadge lane={lane} />
              <span className="flex-1 min-w-0 font-semibold text-ink truncate text-sm">{F.racerName(b) ?? "―"}</span>
              {F.courseNo(b) && <Stat label="進入" value={F.courseNo(b)} />}
              <Stat label="ST" value={fmtSt(F.st(b))} />
              {k && <span className="text-[10px] bg-line text-sub px-1.5 py-0.5 rounded">{k}</span>}
            </div>
          );
        })}
      </div>

      {Array.isArray(payoffs) && payoffs.length > 0 && (
        <div className="mt-3 bg-panel border border-line rounded-lg p-2.5">
          <div className="text-[11px] text-sub2 mb-1.5">払戻金</div>
          <table className="w-full text-xs">
            <tbody>
              {payoffs.map((p, i) => (
                <tr key={i} className="border-t border-line first:border-t-0">
                  <td className="py-1 text-sub">{pick(p, ["type", "bet_type", "payoff_type"], "")}</td>
                  <td className="py-1 text-ink font-semibold">{pick(p, ["combination", "number", "combo"], "")}</td>
                  <td className="py-1 text-right text-amber font-semibold tabular-nums">
                    {Number(pick(p, ["payoff", "amount", "money"], 0)).toLocaleString()}円
                  </td>
                  <td className="py-1 text-right text-sub2 tabular-nums">
                    {pick(p, ["popularity", "pop", "rank"]) ? `${pick(p, ["popularity", "pop", "rank"])}番人気` : ""}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      <RawJson data={race} />
    </div>
  );
}
